#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    const int MAX_STACK = 64;          // maximum stack depth
    long stack[MAX_STACK];
    int top = 0;

    // Need at least one argument (the postfix expression)
    if (argc < 2) {
        puts("ERROR");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        // Prevent stack overflow while pushing a number
        if (top >= MAX_STACK) {
            puts("ERROR");
            return 0;
        }

        char *endptr;
        long val = strtol(argv[i], &endptr, 10);

        // If the whole token is a valid integer, push it
        if (endptr != argv[i] && *endptr == '\0') {
            stack[top++] = val;
            continue;
        }

        // Otherwise the token must be a single‑character operator
        if (strlen(argv[i]) != 1) {
            puts("ERROR");
            return 0;
        }
        char op = argv[i][0];

        // Need at least two operands on the stack for a binary operator
        if (top < 2) {
            puts("ERROR");
            return 0;
        }
        long b = stack[--top];   // right operand
        long a = stack[--top];   // left operand
        long result;

        switch (op) {
            case '+':
                result = a + b;
                break;
            case '-':
                result = a - b;
                break;
            case '*':
                result = a * b;
                break;
            case '/':
                if (b == 0) {
                    puts("ERROR");
                    return 0;
                }
                result = a / b;
                break;
            default:
                puts("ERROR");
                return 0;
        }
        stack[top++] = result;
    }

    // After processing all tokens there must be exactly one value left
    if (top != 1) {
        puts("ERROR");
        return 0;
    }

    printf("%ld\n", stack[0]);
    return 0;
}
